function save(){try{localStorage.setItem(SAVE_KEY,JSON.stringify(S))}catch(e){}}
function lvl(){let n=parseInt(document.getElementById('proLvl')?.textContent||'1',10);return Number.isFinite(n)?n:1}
function uid(){return Date.now().toString(36)+Math.random().toString(36).slice(2,8)}
function deepClone(o){return JSON.parse(JSON.stringify(o))}
function totalAffix(it,stat){return (it?.affixes||[]).reduce((n,a)=>n+(a.stat===stat?(AFFIX[a.id]?.per?.[Math.max(0,a.tier-1)]||0):0),0)}
function uniqueFx(stat){let n=0;for(const it of Object.values(S.equip)){if(it?.uniqueFx&&typeof it.uniqueFx[stat]==='number')n+=it.uniqueFx[stat]}return n}
function nodeFx(){let out={};for(const d of PASSIVES){let [id,,,,,fx]=d;if(!S.passive.nodes[id])continue;for(const [k,v] of Object.entries(fx||{}))out[k]=(out[k]||0)+v}return out}
function skillFx(skill){let out={};let data=S.skills[skill];for(const n of SKILLS[skill].nodes){let [id,,,max,,fx]=n;let r=data.nodes[id]||0;if(!r)continue;for(const [k,v] of Object.entries(fx||{}))out[k]=(out[k]||0)+v*r}return out}
function gearStats(){let out={damage:0,prism:0,void:0,mycelial:0,boss:0,overload:0,wardkill:0,manakill:0,regen:0,fortune:0,forge:0,phase:0};for(const it of Object.values(S.equip)){if(!it)continue;for(const a of it.affixes||[]){let def=AFFIX[a.id];if(!def)continue;out[def.stat]=(out[def.stat]||0)+def.per[Math.max(0,a.tier-1)];}if(it.implicit){out[it.implicit.tag]=(out[it.implicit.tag]||0)+it.implicit.value}}
 return out}
function combined(){let g=gearStats(),p=nodeFx(),m=MASTERY[S.mastery]?.fx||{},o={};for(const src of [g,p,m])for(const [k,v] of Object.entries(src))o[k]=(o[k]||0)+v;for(const stat of ['damage','prism','void','mycelial','boss','overload','wardkill','manakill','regen','fortune','forge','phase','phaseMana','normalPenalty','wardDamage','manaRefund','salvage','craftCrit','shot','fracture','nova','fractureLong'])o[stat]=(o[stat]||0)+uniqueFx(stat);return o}
function activeTags(){let tags=[MASTERY[S.mastery]?.tag||'signal'];let goal=S.goal;if(goal==='PRISM')tags.push('prism','crit');if(goal==='VEIL')tags.push('boss','signal','crit');if(goal==='MYCELIAL')tags.push('mycelial','ward','forge');return [...new Set(tags)]}
function itemPower(it){if(!it)return 0;let p=(it.implicit?.value||0)+it.rarity*8+(it.ilvl||1)*.12;for(const a of it.affixes||[])p+=a.tier*5+(a.tier>=6?10:0);if(it.uniqueFx)p+=24+(it.lp||0)*12;return Math.round(p)}
function rollTier(ilvl,rarity){let r=Math.random(),t=1;if(ilvl>6&&r>.25)t=2;if(ilvl>10&&r>.52)t=3;if(ilvl>16&&r>.70)t=4;if(ilvl>22&&r>.84)t=5;if(rarity>=3&&ilvl>18&&r>.89)t=6;if(rarity>=3&&ilvl>28&&r>.96)t=7;return t}
function rollRarity(boss=false,elite=false){if(boss&&Math.random()<.28)return 4;let q=(combined().fortune||0)/100,roll=Math.random();if(boss&&roll<.58)return 3;if(elite&&roll<.16+q*.35)return 3;if(roll<.025+q*.08)return 4;if(roll<.11+q*.18)return 3;if(roll<.43+q*.20)return 2;if(roll<.78)return 1;return 0}
function rollAffixes(slot,rarity,ilvl){let count=rarity===0?0:rarity===1?1+(Math.random()>.5?1:0):rarity>=2?3+(Math.random()>.45?1:0):0;let list=Object.entries(AFFIX),chosen=[],pk=0,sk=0;let bias=activeTags();for(let i=0;i<count;i++){let options=list.filter(([id,d])=>!chosen.some(a=>a.id===id)&&(d.kind==='prefix'?pk<2:sk<2));if(!options.length)break;let weighted=[];for(const x of options){weighted.push(x);if(bias.includes(x[1].tag))weighted.push(x,x)}let [id,d]=weighted[Math.floor(Math.random()*weighted.length)];let tier=rollTier(ilvl,rarity);if(rarity<3)tier=Math.min(5,tier);chosen.push({id,tier,stat:d.stat});if(d.kind==='prefix')pk++;else sk++;}return chosen}
function makeUnique(slot,ilvl){let pool=UNIQUE.filter(u=>u.slot===slot),u=pool[Math.floor(Math.random()*pool.length)]||UNIQUE[0];return{id:uid(),slot,name:u.name,rarity:4,ilvl,fp:0,affixes:[],implicit:{tag:u.tag,value:8+Math.floor(ilvl/8)},uniqueFx:deepClone(u.fx),uniqueDesc:u.desc,lp:Math.random()<(ilvl>18?.28:.12)?(Math.random()>.72?2:1):0,locked:true}}
function makeItem({boss=false,elite=false,slot=null}={}){let ilvl=Math.max(1,lvl()+Math.floor(Math.random()*4)-1);slot=slot||SLOT_ORDER[Math.floor(Math.random()*SLOT_ORDER.length)];let rarity=rollRarity(boss,elite);if(rarity===4)return makeUnique(slot,ilvl);let base=BASES[slot][Math.floor(Math.random()*BASES[slot].length)],affixes=rollAffixes(slot,rarity,ilvl);let name=base[0],fp=rarity===0?18+Math.floor(Math.random()*8):22+rarity*4+Math.floor(Math.random()*11);return{id:uid(),slot,name,rarity,ilvl,fp,affixes,implicit:{tag:base[2],value:base[1]+Math.floor(ilvl/10)},locked:false,lp:0}}
function rarityText(it){return RAR[it.rarity]?.name||'UNKNOWN'}
function affixLine(a){let d=AFFIX[a.id];if(!d)return 'Unknown';let val=d.per[Math.max(0,a.tier-1)];return `T${a.tier} ${d.name} · +${val}${['wardkill','manakill','regen'].includes(a.stat)?'':'%'}`}
function filterPass(it){if(it.rarity>=3)return true;if(it.rarity<S.filter.min)return false;if(S.filter.preset==='JOURNEY')return true;if(S.filter.preset==='STRICT')return it.rarity>=2&&itemPower(it)>=Math.max(18,lvl()*.9);if(S.filter.preset==='TRANSCENDENT')return it.rarity>=3;let wanted=activeTags().concat(S.filter.wanted||[]);let hit=(it.affixes||[]).some(a=>wanted.includes(AFFIX[a.id]?.tag)&&a.tier>=3)||wanted.includes(it.implicit?.tag);if(it.rarity===1)return S.filter.showMagicWanted&&hit;return it.rarity>=2||hit}
function salvageYield(it,hidden=false){let bonus=hidden?1+(nodeFx().salvage||0)/100:1;for(const a of it.affixes||[]){let n=Math.max(1,Math.floor((a.tier*(.45+Math.random()*.45))*bonus));S.mats[a.id]=(S.mats[a.id]||0)+n}if(it.rarity>=3)S.mats.hope=(S.mats.hope||0)+(Math.random()<.35?1:0);if(it.rarity===4)S.legendaryDust++;S.salvaged++;save()}
function putItem(it){S.found++;if(S.inv.length<36)S.inv.push(it);else if(S.stash.length<160)S.stash.push(it);else salvageYield(it,true);save();renderAll();notify(`${rarityText(it)} · ${it.name}`,RAR[it.rarity].color)}
const ground=[];
function spawnGround(it,pos){if(!filterPass(it)){if(S.filter.autoSalvage)salvageYield(it,true);return}let c=parseInt(RAR[it.rarity].color.slice(1),16),m=new THREE.Mesh(new THREE.OctahedronGeometry(.15+it.rarity*.025,1),new THREE.MeshBasicMaterial({color:c,transparent:true,opacity:.95,depthWrite:false,blending:THREE.AdditiveBlending}));m.position.copy(pos).add(new THREE.Vector3((Math.random()-.5)*.8,.35,(Math.random()-.5)*.8));scene.add(m);let lab=document.createElement('div');lab.className='qAdvDrop';lab.style.color=RAR[it.rarity].color;lab.textContent=(it.rarity>=3?rarityText(it)+' · ':'')+it.name;document.body.appendChild(lab);ground.push({it,m,lab,t:0})}
function notify(text,color='#72eaff'){let box=document.getElementById('qAdvToast');if(!box)return;let d=document.createElement('div');d.style.color=color;d.textContent=text;box.prepend(d);while(box.children.length>5)box.lastChild.remove();setTimeout(()=>{d.style.opacity='0';setTimeout(()=>d.remove(),220)},3400)}
function itemById(id){return S.inv.find(x=>x.id===id)||S.stash.find(x=>x.id===id)||Object.values(S.equip).find(x=>x?.id===id)||null}
function removeById(id){let i=S.inv.findIndex(x=>x.id===id);if(i>=0)return S.inv.splice(i,1)[0];i=S.stash.findIndex(x=>x.id===id);if(i>=0)return S.stash.splice(i,1)[0];return null}
function equipItem(id){let it=removeById(id);if(!it)return;let old=S.equip[it.slot];S.equip[it.slot]=it;if(old)S.inv.length<36?S.inv.push(old):S.stash.push(old);S.selected=it.id;save();recompute();renderAll();notify(`${it.name} EQUIPPED`,RAR[it.rarity].color)}
function unequip(slot){let it=S.equip[slot];if(!it)return;if(S.inv.length<36)S.inv.push(it);else S.stash.push(it);S.equip[slot]=null;save();recompute();renderAll()}
function stashItem(id){let it=removeById(id);if(!it)return;S.stash.push(it);save();renderAll()}
function retrieveItem(id){let i=S.stash.findIndex(x=>x.id===id);if(i<0)return;let it=S.stash.splice(i,1)[0];if(S.inv.length<36)S.inv.push(it);else S.stash.unshift(it);save();renderAll()}
function shatterItem(id){let it=removeById(id);if(!it)return;salvageYield(it,false);if(S.forgeSelected===id)S.forgeSelected=null;renderAll();notify(`SHATTERED · ${it.name}`,'#ff9a47')}
function sortItems(){S.inv.sort((a,b)=>itemPower(b)-itemPower(a));S.stash.sort((a,b)=>itemPower(b)-itemPower(a));save();renderAll()}
function stashAll(){S.stash.push(...S.inv);S.inv=[];save();renderAll()}
function getSkillRank(skill,id){return S.skills[skill]?.nodes?.[id]||0}
function canBuySkill(skill,node){let [id,,,max,req]=node,d=S.skills[skill];if((d.nodes[id]||0)>=max||d.points<=0)return false;return req.every(r=>(d.nodes[r]||0)>0)}
function buySkill(skill,id){let node=SKILLS[skill].nodes.find(n=>n[0]===id),d=S.skills[skill];if(!node)return;if((d.nodes[id]||0)>0){let depend=SKILLS[skill].nodes.some(n=>(d.nodes[n[0]]||0)>0&&(n[4]||[]).includes(id));if(depend)return notify('REFUND CONNECTED NODES FIRST','#ff9a70');d.nodes[id]--;d.points++;save();renderSkills();recompute();return}if(!canBuySkill(skill,node))return;d.nodes[id]=1;d.points--;save();renderSkills();recompute()}
function addSkillXP(skill,n){let d=S.skills[skill];if(!d)return;d.xp+=n;let need=30+d.level*22;while(d.xp>=need&&d.level<20){d.xp-=need;d.level++;d.points++;need=30+d.level*22;notify(`${SKILLS[skill].name} · SPECIALIZATION ${d.level}`,'#72eaff')}save()}
function toggleSupport(skill,id){let d=S.skills[skill],sup=SUPPORTS[id];if(!sup||!sup.skills.includes(skill))return;let i=d.supports.indexOf(id);if(i>=0)d.supports.splice(i,1);else{if(d.supports.length>=2)d.supports.shift();d.supports.push(id)}save();renderSkills();recompute()}
function passiveNode(id){return PASSIVES.find(n=>n[0]===id)}
function canBuyPassive(n){let [id,,,type,req]=n;if(id==='root'||S.passive.nodes[id]||S.passive.points<=0)return false;return req.every(r=>S.passive.nodes[r])}
function buyPassive(id){let n=passiveNode(id);if(!n)return;if(S.passive.nodes[id]){let dep=PASSIVES.some(x=>S.passive.nodes[x[0]]&&(x[4]||[]).includes(id));if(dep)return notify('REFUND CONNECTED NODES FIRST','#ff9a70');if(id==='root')return;delete S.passive.nodes[id];S.passive.points++;save();renderPassives();recompute();return}if(!canBuyPassive(n))return;S.passive.nodes[id]=1;S.passive.points--;save();renderPassives();recompute()}
function chooseMastery(id){if(!MASTERY[id])return;let danger=enemies?.some(e=>!e.dead&&e.g.position.distanceTo(player.position)<6);if(danger)return notify('MASTERY TUNING LOCKED DURING COMBAT','#ff8e6b');S.mastery=id;save();recompute();renderPassives();renderGear();notify(`${MASTERY[id].name} ACQUIRED`,'#ffd16b')}
function recompute(){let c=combined();try{MAX.fc=.18*(1-Math.min(.24,(c.phase||0)/160));MAX.pc=2.2*(1-Math.min(.2,(c.phase||0)/180));MAX.qc=5.5;MAX.ec=7.5;MAX.dc=1.05*(1-Math.min(.22,(c.phase||0)/150))}catch(e){}renderBuildReadout()}
function listedMana(skill){return{shot:1,prism:18,nova:28,fracture:34}[skill]||0}
function supportHas(skill,id){return S.skills[skill].supports.includes(id)}
function skillMod(skill){let sf=skillFx(skill),c=combined(),pct=(c.damage||0)+(sf.dmg||0);if(skill==='shot')pct+=(c.shot||0);if(skill==='prism')pct+=(c.prism||0);if(skill==='nova')pct+=(c.prism||0)+(c.nova||0)*.5; if(skill==='fracture')pct+=(c.void||0)+(c.mycelial||0)+(c.fracture||0);if(supportHas(skill,'heavy'))pct+=22;if(supportHas(skill,'execution'))pct+=0;return{pct,boss:(c.boss||0)+(sf.boss||0)+(supportHas(skill,'execution')?28:0),extra:(sf.extra||0)+uniqueFx(skill==='prism'?'prismRays':'none'),wide:(sf.wide||0)+(supportHas(skill,'bloom')?1:0),long:(sf.long||0)+(supportHas(skill,'bloom')?1:0)+(c.fractureLong||0)+uniqueFx('fractureLong'),burst:(sf.burst||0)+uniqueFx('fractureBurst'),ward:(sf.ward||0),mana:(sf.mana||0)}}
let castContext=null,phasePrimed=false;
const oldFire=fire;fire=function(dir,speed,damage,color,size,life){let sk=castContext||'shot',mod=skillMod(sk);let mult=1+mod.pct/100;if(supportHas(sk,'swift')){speed*=1.16;mult*=1.08}if(supportHas(sk,'heavy'))mult*=1.22;oldFire(dir,speed,damage*mult,color,size,life)};
const oldShot=signalShot;signalShot=function(){let ready=fc<=0&&manav>=1;if(!ready)return oldShot();let mod=skillMod('shot'),before=manav;castContext='shot';oldShot();castContext=null;addSkillXP('shot',2);if(mod.extra){let d=aimDir();for(let i=0;i<mod.extra;i++){let a=(i%2?1:-1)*(.09+.04*Math.floor(i/2));castContext='shot';fire(d.clone().applyAxisAngle(new THREE.Vector3(0,1,0),a),15,24,0xbf63ff,.085,1.5);castContext=null}}let echoChance=(getSkillRank('shot','shot_echo')?20:0)+uniqueFx('echoShot')*100;if(echoChance&&Math.random()<Math.min(.9,echoChance/100)){setTimeout(()=>{if(!running)return;let d=aimDir();for(const a of [-.04,0,.04]){castContext='shot';fire(d.clone().applyAxisAngle(new THREE.Vector3(0,1,0),a),15,uniqueFx('echoShot')?16:18,0x8d6bff,.08,1.25);castContext=null}},170)}if(supportHas('shot','sustain'))manav=Math.min(150,manav+3);refundMana('shot',before)};
const oldPrism=prism;prism=function(){let ready=pc<=0&&manav>=18;if(!ready)return oldPrism();let mod=skillMod('prism'),before=manav;castContext='prism';oldPrism();castContext=null;addSkillXP('prism',5);let extra=(getSkillRank('prism','prism_fan')?2:0)+uniqueFx('prismRays');if(extra){let d=aimDir();for(let i=0;i<extra;i++){let a=(i%2?1:-1)*(.19+.045*Math.floor(i/2));castContext='prism';fire(d.clone().applyAxisAngle(new THREE.Vector3(0,1,0),a),19,44,0x55eaff,.11,1.5);castContext=null}}if(getSkillRank('prism','prism_key'))setTimeout(()=>{if(!running)return;let d=aimDir();for(const a of [-.04,0,.04]){castContext='prism';fire(d.clone().applyAxisAngle(new THREE.Vector3(0,1,0),a),21,32,0xb5f7ff,.09,1.2);castContext=null}},210);let ward=getSkillRank('prism','prism_ward')*2;if(ward)shieldv=Math.min(50,shieldv+ward);if(supportHas('prism','sustain'))manav=Math.min(150,manav+3);refundMana('prism',before)};
const oldNova=nova;nova=function(){let ready=qc<=0&&manav>=28;if(!ready)return oldNova();let mod=skillMod('nova'),before=manav;castContext='nova';oldNova();castContext=null;addSkillXP('nova',8);let rad=5.3+(mod.wide?1.1+.45*Math.min(2,mod.wide):0)+uniqueFx('novaWide')*.8;if(rad>5.3){for(const e of enemies)if(!e.dead){let d=e.g.position.distanceTo(player.position);if(d>5.3&&d<rad){castContext='nova';hitEnemy(e,58);castContext=null}}}let touched=enemies.filter(e=>!e.dead&&e.g.position.distanceTo(player.position)<rad).length,ward=(getSkillRank('nova','nova_ward')+uniqueFx('novaWard'))*Math.min(6,touched);if(ward)shieldv=Math.min(50,shieldv+ward);if(getSkillRank('nova','nova_key'))setTimeout(()=>{if(!running)return;for(const e of enemies)if(!e.dead&&e.g.position.distanceTo(player.position)<rad){castContext='nova';hitEnemy(e,45);castContext=null}try{flash(player.position,0xd45cff,18)}catch(e){}},350);if(supportHas('nova','sustain'))manav=Math.min(150,manav+3);refundMana('nova',before)};
const oldFracture=fracture;fracture=function(){let ready=ec<=0&&manav>=34;if(!ready)return oldFracture();let mod=skillMod('fracture'),before=manav,at=aim.clone();castContext='fracture';oldFracture();castContext=null;addSkillXP('fracture',9);let linger=getSkillRank('fracture','frac_long')+mod.long;if(linger){let fld=[...fx].reverse().find(x=>x.type==='field');if(fld)fld.t-=Math.min(3,linger*.65)}let burst=getSkillRank('fracture','frac_burst')+mod.burst;if(burst){let rad=2.4+.35*Math.min(3,burst);for(const e of enemies)if(!e.dead&&e.g.position.distanceTo(at)<rad){castContext='fracture';hitEnemy(e,40+burst*13);castContext=null}try{flash(at,0x7c5cff,18)}catch(e){}}if(getSkillRank('fracture','frac_key')){setTimeout(()=>{for(const e of enemies)if(!e.dead&&e.g.position.distanceTo(at)<3.8){castContext='fracture';hitEnemy(e,38);castContext=null}},500);setTimeout(()=>{for(const e of enemies)if(!e.dead&&e.g.position.distanceTo(at)<3.8){castContext='fracture';hitEnemy(e,38);castContext=null}},1050)}manav=Math.min(150,manav+getSkillRank('fracture','frac_mana')*4);if(supportHas('fracture','sustain'))manav=Math.min(150,manav+3);refundMana('fracture',before)};
function refundMana(skill,before){let c=combined(),refund=(c.manaRefund||0)/100,flat=skillFx(skill).mana||0;if(refund||flat){let spent=Math.max(0,before-manav);manav=Math.min(150,manav+spent*refund+flat)}if(supportHas(skill,'heavy'))manav=Math.max(0,manav-listedMana(skill)*.18)}
const oldDash=dash;dash=function(){let ready=dc<=0;oldDash();if(ready){let c=combined(),give=(c.phaseMana||0)+uniqueFx('phaseMana');if(give)manav=Math.min(150,manav+give);if((c.phasePrime||0)||uniqueFx('phasePrime'))phasePrimed=true}};
const oldHit=hitEnemy;hitEnemy=function(e,d){if(!e||e.dead)return;let c=combined(),sk=castContext,mod=sk?skillMod(sk):{boss:c.boss||0},mult=1;if(e.boss||e.proRank===2)mult*=1+(mod.boss||0)/100;else if(c.normalPenalty)mult*=1-c.normalPenalty/100;if(c.wardDamage&&shieldv>25)mult*=1+c.wardDamage/100;if(uniqueFx('wardDamage')&&shieldv>25)mult*=1+uniqueFx('wardDamage')/100;if(phasePrimed){mult*=1.30;phasePrimed=false;notify('PHASE-PRIMED HIT','#72eaff')}let overload=(c.overload||0)+uniqueFx('overload');if(overload>0&&Math.random()<overload/100){mult*=1.55;shieldv=Math.min(50,shieldv+uniqueFx('overloadWard'));notify('SIGNAL OVERLOAD','#ffe17a')}oldHit(e,d*mult)};
const oldKill=killEnemy;killEnemy=function(e){if(!e||e.dead)return;let pos=e.g.position.clone(),elite=e.proRank===2,bossy=!!e.boss;oldKill(e);let c=combined();shieldv=Math.min(50,shieldv+(c.wardkill||0));manav=Math.min(150,manav+(c.manakill||0));let count=bossy?3:elite&&Math.random()>.55?2:1;for(let i=0;i<count;i++){let it=makeItem({boss:bossy,elite});spawnGround(it,pos)}save()};

