const filterPage=mkPage('qFilterAdv',`<div class="qSectionTitle">LOOT SIGNAL FILTER</div><div class="qMeta">High-value Exalted, Unique and Legendary signals always show. Hidden gear can be auto-shattered into affix shards so filtering never means wasting progression.</div><div id="qPresets" class="qFilterPresets"></div><div class="qSectionTitle" style="margin-top:16px">SMART-LOOT TAGS</div><div id="qChecks" class="qCheckGrid"></div><div class="qActions"><button id="qFilterExport" class="qMiniBtn">EXPORT FILTER</button><button id="qFilterImport" class="qMiniBtn">IMPORT FILTER</button><label class="qCheck"><input type="checkbox" id="qAutoSalvage"> AUTO-SHATTER HIDDEN</label></div><div class="qMeta" id="qFilterStats" style="margin-top:15px"></div>`);
function showAdv(id){document.querySelectorAll('#qMenu .qPage').forEach(p=>p.classList.remove('on'));document.querySelectorAll('#qMenuHead .qTab').forEach(b=>b.classList.remove('on'));let p={gear:gearPage,passive:passivePage,skills:skillsPage,forge:forgePage,filter:filterPage}[id];if(p)p.classList.add('on');let b=id==='gear'?oldInvTab:id==='passive'?oldTreeTab:head.querySelector(`[data-adv="${id}"]`);if(b)b.classList.add('on');if(id==='gear')renderGear();if(id==='passive')renderPassives();if(id==='skills')renderSkills();if(id==='forge')renderForge();if(id==='filter')renderFilter()}
function openAdv(id){let shade=document.getElementById('qMenuShade');if(!shade.classList.contains('on'))window.dispatchEvent(new KeyboardEvent('keydown',{key:'i',bubbles:true}));setTimeout(()=>showAdv(id),0)}
if(oldInvTab)oldInvTab.onclick=()=>showAdv('gear');if(oldTreeTab)oldTreeTab.onclick=()=>showAdv('passive');skillTab.onclick=()=>showAdv('skills');forgeTab.onclick=()=>showAdv('forge');filterTab.onclick=()=>showAdv('filter');
addEventListener('keydown',e=>{if(e.repeat)return;let k=e.key.toLowerCase();if(k==='i')setTimeout(()=>{if(document.getElementById('qMenuShade').classList.contains('on'))showAdv('gear')},0);else if(k==='p')setTimeout(()=>{if(document.getElementById('qMenuShade').classList.contains('on'))showAdv('passive')},0);else if(k==='k'){e.preventDefault();openAdv('skills')}else if(k==='g'){e.preventDefault();openAdv('forge')}else if(k==='l'){e.preventDefault();openAdv('filter')}});
let view='inv',search='';
function itemMatches(it){let q=search.trim().toLowerCase();if(!q)return true;let s=[it.name,it.slot,rarityText(it),...(it.affixes||[]).map(a=>AFFIX[a.id]?.name||'')].join(' ').toLowerCase();return s.includes(q)}
function itemCard(it,where){let d=document.createElement('div');d.className='qCard'+(S.selected===it.id?' sel':'');d.style.color=RAR[it.rarity].color;d.innerHTML=`<span class="qScore">${itemPower(it)}</span><b>${it.name}</b><div class="meta">${rarityText(it)} · ${SLOT_NAME[it.slot]} · i${it.ilvl}</div><div class="aff">${it.uniqueDesc||((it.affixes||[]).slice(0,3).map(affixLine).join('<br>')||'No affixes')}</div>`;d.onclick=()=>{S.selected=it.id;save();renderGear()};d.ondblclick=()=>where==='inv'?equipItem(it.id):retrieveItem(it.id);return d}
function renderGear(){let eq=document.getElementById('qEquip');if(!eq)return;eq.innerHTML='';for(const slot of SLOT_ORDER){let it=S.equip[slot],d=document.createElement('div');d.className='qSlot';d.innerHTML=`<b>${SLOT_NAME[slot]}</b><span style="color:${it?RAR[it.rarity].color:'#615869'}">${it?it.name:'EMPTY'}</span><small style="color:#776f7d;font:7px system-ui">${it?'POWER '+itemPower(it):'CLICK TO UNEQUIP'}</small>`;d.onclick=()=>it&&unequip(slot);eq.appendChild(d)}let c=combined(),st=document.getElementById('qStats');st.innerHTML=`<span class="qStatStrong">${MASTERY[S.mastery].name}</span><br>All damage +${Math.round(c.damage||0)}% · Prism +${Math.round(c.prism||0)}%<br>Boss +${Math.round(c.boss||0)}% · Overload ${Math.round(c.overload||0)}%<br>Ward/kill ${Number(c.wardkill||0).toFixed(1)} · Mana/kill ${Number(c.manakill||0).toFixed(1)}<br>Loot quality +${Math.round(c.fortune||0)}% · Forge efficiency +${Math.round(c.forge||0)}%`;let arr=(view==='stash'?S.stash:S.inv).filter(itemMatches),cards=document.getElementById('qCards');cards.innerHTML='';for(const it of arr)cards.appendChild(itemCard(it,view));let sel=itemById(S.selected),det=document.getElementById('qDetail');renderDetail(det,sel);document.getElementById('qView').value=view;}
function renderDetail(det,it){if(!det)return;if(!it){det.innerHTML='<h3>ITEM INSPECTOR</h3><div class="qMeta">SELECT AN ITEM</div>';return}let equipped=S.equip[it.slot],compare=equipped&&equipped.id!==it.id?itemPower(it)-itemPower(equipped):0;det.style.color=RAR[it.rarity].color;det.innerHTML=`<div class="rar">${rarityText(it)} · ${SLOT_NAME[it.slot]} · ITEM LEVEL ${it.ilvl}</div><h2>${it.name}</h2><div class="implicit">IMPLICIT · +${it.implicit.value}% ${it.implicit.tag.toUpperCase()}</div>${it.uniqueDesc?`<div class="unique">${it.uniqueDesc}</div>`:''}<div class="line">${(it.affixes||[]).map(affixLine).join('<br>')||'No crafted affixes'}</div><div class="qMeta" style="margin-top:8px">POWER ${itemPower(it)} ${compare?`· ${compare>0?'+':''}${compare} VS EQUIPPED`:''}<br>${it.locked?'UNIQUE · FORGE LOCKED':'FORGING POTENTIAL '+it.fp}${it.lp?' · LEGENDARY POTENTIAL '+it.lp:''}</div><div class="qActions"><button class="qMiniBtn" data-a="equip">EQUIP</button><button class="qMiniBtn" data-a="forge">FORGE</button><button class="qMiniBtn" data-a="stash">STASH</button><button class="qMiniBtn" data-a="shatter">SHATTER</button></div>`;det.querySelector('[data-a="equip"]').onclick=()=>equipItem(it.id);det.querySelector('[data-a="forge"]').onclick=()=>{S.forgeSelected=it.id;save();showAdv('forge')};det.querySelector('[data-a="stash"]').onclick=()=>stashItem(it.id);det.querySelector('[data-a="shatter"]').onclick=()=>shatterItem(it.id)}
document.getElementById('qSearch').oninput=e=>{search=e.target.value;renderGear()};document.getElementById('qView').onchange=e=>{view=e.target.value;renderGear()};document.getElementById('qSort').onclick=sortItems;document.getElementById('qStashAll').onclick=stashAll;
function renderPassives(){let pts=document.getElementById('qPPoints');if(!pts)return;pts.textContent=`UNSPENT SIGNAL POINTS · ${S.passive.points}`;let temp=document.getElementById('qTemplates');temp.innerHTML='';for(const [id,b] of Object.entries(BUILD_TEMPLATES)){let x=document.createElement('button');x.className='qMaster'+(S.goal===id?' on':'');x.innerHTML=`<b>${b.name}</b>Highlight a coherent route without auto-spending points.`;x.onclick=()=>{S.goal=id;save();renderPassives();renderSkills();renderFilter()};temp.appendChild(x)}let mas=document.getElementById('qMasteries');mas.innerHTML='';for(const [id,m] of Object.entries(MASTERY)){let x=document.createElement('button');x.className='qMaster'+(S.mastery===id?' on':'');x.innerHTML=`<b>${m.name}</b>${m.desc}`;x.onclick=()=>chooseMastery(id);mas.appendChild(x)}let tr=document.getElementById('qPassiveTree');tr.innerHTML='';let goal=BUILD_TEMPLATES[S.goal]?.nodes||[];for(const n of PASSIVES){let [id,name,desc,type,req,,x,y]=n,b=document.createElement('button');b.className='qPNode '+type+(S.passive.nodes[id]?' on':'')+(goal.includes(id)?' goal':'');b.style.left=x+'%';b.style.top=y+'%';b.innerHTML=`<b>${name}</b><br>${desc}`;b.disabled=id!=='root'&&!S.passive.nodes[id]&&!canBuyPassive(n);b.onclick=()=>buyPassive(id);tr.appendChild(b)}}
let activeSkill='shot';function renderSkills(){let tabs=document.getElementById('qSkillTabs');if(!tabs)return;tabs.innerHTML='';for(const [id,s] of Object.entries(SKILLS)){let b=document.createElement('button');b.className='qSkillTab'+(id===activeSkill?' on':'');b.style.color=s.color;b.textContent=`${s.key} · ${s.name}`;b.onclick=()=>{activeSkill=id;renderSkills()};tabs.appendChild(b)}let d=S.skills[activeSkill],need=30+d.level*22,info=document.getElementById('qSkillInfo');info.textContent=`SKILL LEVEL ${d.level}/20 · ${d.points} UNSPENT · XP ${Math.round(d.xp)}/${need}`;let tree=document.getElementById('qSkillTree');tree.innerHTML='';let goal=BUILD_TEMPLATES[S.goal]?.skills?.[activeSkill]||[];for(const n of SKILLS[activeSkill].nodes){let [id,name,desc,max,,,x,y]=n,b=document.createElement('button'),rank=d.nodes[id]||0;b.className='qSkillNode'+(rank?' on':'')+(goal.includes(id)?' goal':'');b.style.left=x+'%';b.style.top=y+'%';b.innerHTML=`<b>${name}</b>${desc}<br><span style="color:#72eaff">${rank}/${max}</span>`;b.disabled=!rank&&!canBuySkill(activeSkill,n);b.onclick=()=>buySkill(activeSkill,id);tree.appendChild(b)}let sups=document.getElementById('qSupports');sups.innerHTML='';for(const [id,s] of Object.entries(SUPPORTS)){if(!s.skills.includes(activeSkill))continue;let b=document.createElement('button');b.className='qSupport'+(d.supports.includes(id)?' on':'');b.innerHTML=`<b>${s.name}</b><br>${s.desc}`;b.onclick=()=>toggleSupport(activeSkill,id);sups.appendChild(b)}}
function renderForge(){let it=itemById(S.forgeSelected)||itemById(S.selected),box=document.getElementById('qForgeItem');if(it)S.forgeSelected=it.id;if(!it){box.innerHTML='<div class="qMeta">Select an item from Gear and choose FORGE.</div>';document.getElementById('qForgeAffixes').innerHTML='';renderMats();return}box.style.color=RAR[it.rarity].color;box.innerHTML=`<div class="rar">${rarityText(it)} · ${SLOT_NAME[it.slot]}</div><h2>${it.name}</h2><div class="implicit">FORGING POTENTIAL · ${it.fp}</div><div class="line">${(it.affixes||[]).map(affixLine).join('<br>')||'No affixes'}</div>${it.locked?'<div class="unique">Unique signals cannot be directly forged. Ascendance works on non-unique items.</div>':''}`;let af=document.getElementById('qForgeAffixes');af.innerHTML='';for(let i=0;i<(it.affixes||[]).length;i++){let a=it.affixes[i],d=document.createElement('div');d.className='qForgeAff';d.innerHTML=`<b>${affixLine(a)}</b><div class="qActions"><button class="qMiniBtn">UPGRADE WITH ${AFFIX[a.id].name.toUpperCase()} SHARD · ${S.mats[a.id]||0}</button></div>`;d.querySelector('button').onclick=()=>forgeUpgrade(it.id,i);af.appendChild(d)}if(!it.locked&&it.affixes.length<4){for(const [id,a] of Object.entries(AFFIX)){let same=it.affixes.some(x=>x.id===id),pk=it.affixes.filter(x=>AFFIX[x.id].kind==='prefix').length,sk=it.affixes.filter(x=>AFFIX[x.id].kind==='suffix').length;if(same||(a.kind==='prefix'?pk>=2:sk>=2)||(S.mats[id]||0)<1)continue;let d=document.createElement('div');d.className='qForgeAff';d.innerHTML=`<b>ADD T1 · ${a.name}</b><div class="qMeta">${a.kind.toUpperCase()} · ${S.mats[id]||0} SHARDS</div>`;d.onclick=()=>forgeAdd(it.id,id);af.appendChild(d)}}renderMats()}
function useFP(it,base=3){let c=combined(),eff=Math.min(.65,(c.forge||0)/100),cost=Math.max(1,Math.ceil(base*(1-eff)*(0.72+Math.random()*.55)));let hope=(S.mats.hope||0)>0&&Math.random()<.25;if(hope){S.mats.hope--;cost=0;notify('GLYPH OF HOPE · POTENTIAL PRESERVED','#72eaff')}it.fp=Math.max(0,it.fp-cost);return cost}
function craftCrit(){return Math.random()<(.08+(combined().craftCrit||0)/100)}
function forgeUpgrade(id,index){let it=itemById(id);if(!it||it.locked||it.fp<=0)return;let a=it.affixes[index];if(!a||a.tier>=5)return notify(a?.tier>=6?'EXALTED TIER IS DROP-ONLY':'CRAFTED TIER CAP REACHED','#ffcf72');if((S.mats[a.id]||0)<1)return notify('MISSING AFFIX SHARD','#ff8e70');S.mats[a.id]--;a.tier++;useFP(it,3+a.tier*.4);if(craftCrit()){let other=it.affixes.filter(x=>x!==a&&x.tier<5);if(other.length){other[Math.floor(Math.random()*other.length)].tier++;notify('CRITICAL FORGE · BONUS AFFIX UPGRADED','#ffe17a')}}save();renderForge();renderGear()}
function forgeAdd(id,aff){let it=itemById(id);if(!it||it.locked||it.fp<=0||(S.mats[aff]||0)<1)return;let def=AFFIX[aff],same=it.affixes.some(x=>x.id===aff),kindN=it.affixes.filter(x=>AFFIX[x.id].kind===def.kind).length;if(same||kindN>=2||it.affixes.length>=4)return;S.mats[aff]--;it.affixes.push({id:aff,tier:1,stat:def.stat});useFP(it,3);save();renderForge();renderGear()}
function forgeRefine(){let it=itemById(S.forgeSelected);if(!it||it.locked||it.fp<=0)return;if((S.mats.refraction||0)<1)return notify('NO RUNE OF REFRACTION','#ff8e70');S.mats.refraction--;for(const a of it.affixes){if(Math.random()<.18&&a.tier>1)a.tier--;else if(Math.random()<.32&&a.tier<5)a.tier++}useFP(it,4);save();renderForge();renderGear();notify('AFFIX VALUES REFRACTED','#72eaff')}
function forgeAscend(){let it=itemById(S.forgeSelected);if(!it||it.locked)return;if((S.mats.ascendance||0)<1)return notify('NO RUNE OF ASCENDANCE','#ff8e70');S.mats.ascendance--;let u=makeUnique(it.slot,it.ilvl),arr=S.inv.findIndex(x=>x.id===it.id),st=S.stash.findIndex(x=>x.id===it.id);if(arr>=0)S.inv[arr]=u;else if(st>=0)S.stash[st]=u;S.forgeSelected=u.id;S.selected=u.id;save();renderForge();renderGear();notify(`ASCENDED · ${u.name}`,'#ff9a47')}
function renderMats(){let m=document.getElementById('qMats');m.innerHTML='';for(const [id,n] of Object.entries(S.mats)){let d=document.createElement('div');d.className='qMat';d.innerHTML=`<b>${id.toUpperCase()}</b><br>${n}`;m.appendChild(d)}}
document.getElementById('qForgeRefine').onclick=forgeRefine;document.getElementById('qForgeAscend').onclick=forgeAscend;document.getElementById('qForgeShatter').onclick=()=>{let id=S.forgeSelected;if(id)shatterItem(id);renderForge()};
const PRESETS={JOURNEY:{min:0,showMagicWanted:true,desc:'Show nearly everything while learning.'},SMART:{min:1,showMagicWanted:true,desc:'Show useful Magic items plus Rare+; bias to your build.'},STRICT:{min:2,showMagicWanted:false,desc:'Rare upgrades and all chase items.'},TRANSCENDENT:{min:3,showMagicWanted:false,desc:'Only Exalted, Unique and Legendary signals.'}};
function renderFilter(){let p=document.getElementById('qPresets');if(!p)return;p.innerHTML='';for(const [id,x] of Object.entries(PRESETS)){let b=document.createElement('button');b.className='qPreset'+(S.filter.preset===id?' on':'');b.innerHTML=`<b>${id}</b>${x.desc}`;b.onclick=()=>{S.filter.preset=id;S.filter.min=x.min;S.filter.showMagicWanted=x.showMagicWanted;save();renderFilter()};p.appendChild(b)}let ch=document.getElementById('qChecks');ch.innerHTML='';for(const tag of ['signal','prism','void','mycelial','boss','crit','ward','forge']){let l=document.createElement('label');l.className='qCheck';l.innerHTML=`<input type="checkbox" ${S.filter.wanted.includes(tag)?'checked':''}> ${tag.toUpperCase()}`;l.querySelector('input').onchange=e=>{if(e.target.checked&&!S.filter.wanted.includes(tag))S.filter.wanted.push(tag);if(!e.target.checked)S.filter.wanted=S.filter.wanted.filter(x=>x!==tag);save()};ch.appendChild(l)}let a=document.getElementById('qAutoSalvage');a.checked=!!S.filter.autoSalvage;a.onchange=e=>{S.filter.autoSalvage=e.target.checked;save()};document.getElementById('qFilterStats').textContent=`${S.found} ITEMS RECOVERED · ${S.salvaged} SIGNALS SHATTERED · ${S.legendaryDust} LEGENDARY DUST · SMART BIAS: ${activeTags().join(' / ').toUpperCase()}`}
document.getElementById('qFilterExport').onclick=async()=>{let t=JSON.stringify(S.filter);try{await navigator.clipboard.writeText(t);notify('FILTER COPIED TO CLIPBOARD','#72eaff')}catch(e){prompt('Copy filter JSON',t)}};document.getElementById('qFilterImport').onclick=()=>{let t=prompt('Paste Quetopia loot filter JSON');if(!t)return;try{S.filter=Object.assign(S.filter,JSON.parse(t));save();renderFilter();notify('FILTER IMPORTED','#72eaff')}catch(e){notify('INVALID FILTER DATA','#ff6f70')}};
document.getElementById('qExportBuild').onclick=async()=>{let b={mastery:S.mastery,passive:S.passive,skills:S.skills,goal:S.goal},t=JSON.stringify(b);try{await navigator.clipboard.writeText(t);notify('BUILD CODE COPIED','#72eaff')}catch(e){prompt('Copy build code',t)}};document.getElementById('qImportBuild').onclick=()=>{let t=prompt('Paste Quetopia build code');if(!t)return;try{let b=JSON.parse(t);if(b.passive&&b.skills){S.mastery=b.mastery||'UNBOUND';S.passive=b.passive;S.skills=b.skills;S.goal=b.goal||'PRISM';save();recompute();renderPassives();notify('BUILD IMPORTED','#72eaff')}}catch(e){notify('INVALID BUILD CODE','#ff6f70')}};
function renderBuildReadout(){let c=combined(),el=document.getElementById('qBuildReadout');if(el)el.textContent=`${MASTERY[S.mastery].name} · DMG +${Math.round(c.damage||0)}% · BOSS +${Math.round(c.boss||0)}% · LOOT +${Math.round(c.fortune||0)}% · I GEAR · P TREE · K SKILLS · G FORGE · L FILTER`}
function renderAll(){renderGear();renderPassives();renderSkills();renderFilter();renderBuildReadout()}
let last=performance.now(),regenAcc=0;function frame(){let now=performance.now(),dt=Math.min(.08,(now-last)/1000);last=now;if(!Number.isFinite(dt)||dt<=0)dt=.016;let cl=lvl();if(cl>S.lastLevel){let gained=cl-S.lastLevel;S.passive.points+=gained;for(const k of Object.keys(S.skills)){S.skills[k].xp+=gained*10}S.lastLevel=cl;save();renderPassives();renderSkills();notify(`LEVEL ${cl} · ${gained} SIGNAL POINT${gained>1?'S':''}`,'#ffd16b')}regenAcc+=dt;if(regenAcc>.5){regenAcc=0;let r=combined().regen||0;if(r)manav=Math.min(150,manav+r*.5)}for(let i=ground.length-1;i>=0;i--){let g=ground[i];g.t+=dt;g.m.rotation.y+=dt*(1.5+g.it.rarity*.2);g.m.position.y=.32+Math.sin(g.t*3)*.07;let p=proj(g.m.position.clone().add(new THREE.Vector3(0,.25,0)));g.lab.style.left=p.x+'px';g.lab.style.top=p.y+'px';if(g.m.position.distanceTo(player.position)<1.15){scene.remove(g.m);g.lab.remove();putItem(g.it);ground.splice(i,1)}else if(g.t>45){scene.remove(g.m);g.lab.remove();ground.splice(i,1)}}requestAnimationFrame(frame)}
recompute();renderAll();requestAnimationFrame(frame);
window.Q_ARPG={state:S,save,makeItem,combined,filterPass,open:(p)=>openAdv(p||'gear')};
